import backtrader as bt


class StopLossATRStrategy(bt.Strategy):
    params = dict(
        sma_period=20,
        atr_period=14,
        take_profit_pct=0.02,
        atr_stop_mult=2.0,
        position_pct=0.01,
    )

    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=self.p.sma_period)
        self.atr = bt.indicators.AverageTrueRange(self.data, period=self.p.atr_period)
        self.order = None
        self.stop_price = None
        self.take_profit_price = None

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.isbuy():
                entry_price = order.executed.price
                self.stop_price = entry_price - self.p.atr_stop_mult * self.atr[0]
                self.take_profit_price = entry_price * (1 + self.p.take_profit_pct)
            else:
                self.stop_price = None
                self.take_profit_price = None
        if order.status in (order.Completed, order.Canceled, order.Margin, order.Rejected):
            self.order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.data.close[0] > self.sma[0]:
                size = (self.p.position_pct * self.broker.getvalue()) / self.data.close[0]
                self.order = self.buy(size=size)
        else:
            if self.data.low[0] <= self.stop_price:
                self.order = self.close()
            elif self.data.high[0] >= self.take_profit_price:
                self.order = self.close()
